import{_ as i,o as s,c as a,a6 as t}from"./chunks/framework.Dtv7txdI.js";const k=JSON.parse('{"title":"CLI Commands","description":"","frontmatter":{},"headers":[],"relativePath":"v1/server/cli.md","filePath":"v1/server/cli.md","lastUpdated":1787648967000}'),n={name:"v1/server/cli.md"};function l(o,e,r,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="cli-commands" tabindex="-1">CLI Commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to “CLI Commands”">​</a></h1><p>Everything the <code>nitr</code> binary can do. Run <code>nitr --help</code> for the same list at the terminal.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Usage: nitr [OPTIONS] [COMMAND]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  run       Start the server (the default when no command is given)</span></span>
<span class="line"><span>  dev       Start the server in development mode (hot reload)</span></span>
<span class="line"><span>  check     Load the configuration and scripts, then exit</span></span>
<span class="line"><span>  test      Run the Lua tests against an in-process server</span></span>
<span class="line"><span>  migrate   Apply pending SQL migrations from migrations/</span></span>
<span class="line"><span>  init      Scaffold a new Nitr application</span></span>
<span class="line"><span>  build     Package the application and this binary into one runnable file</span></span>
<span class="line"><span>  reload    Ask a running server (found via its \`pidfile\`) to reload</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -v, --version        Print the version and exit</span></span>
<span class="line"><span>  -c, --config &lt;PATH&gt;  Path to the TOML config file (default: ./nitr.toml)</span></span>
<span class="line"><span>      --dev            Enable development mode (hot reload)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Signals:</span></span>
<span class="line"><span>  SIGHUP               Zero-downtime reload: rebuilds the Lua runtime pool</span></span></code></pre></div><h2 id="global-options" tabindex="-1">Global options <a class="header-anchor" href="#global-options" aria-label="Permalink to “Global options”">​</a></h2><p>These apply to every command.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-c</code>, <code>--config &lt;PATH&gt;</code></td><td>The TOML configuration file. Defaults to <code>./nitr.toml</code>; if that file does not exist, Nitr starts with built-in defaults rather than failing.</td></tr><tr><td><code>--dev</code></td><td>Turns on development mode — identical to <code>nitr dev</code>, and to <code>dev_mode = true</code> in the file.</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>Print the version and exit.</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">Relative paths resolve against the config file</p><p></p><p>Paths inside <code>nitr.toml</code> (<code>handler_script</code>, <code>[static] dir</code>, …) resolve relative to the file&#39;s directory, so <code>nitr -c /srv/app/nitr.toml run</code> works from anywhere. The one exception is the <strong>env file</strong>, which is external state like the database and resolves against the working directory for a <a href="./deployment/single-file">bundled build</a>.</p></div><h2 id="run" tabindex="-1"><code>run</code> <a class="header-anchor" href="#run" aria-label="Permalink to “run”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or just: nitr</span></span></code></pre></div><p>Starts the server. This is the default when no command is given.</p><ul><li>Binds <code>listen</code>, builds the Lua state pool, applies the configuration.</li><li>Writes the <code>pidfile</code>, if one is configured — <strong>only after</strong> the build succeeded, so a pid that never served is never left behind for <code>nitr reload</code> to signal.</li><li>On <code>SIGTERM</code>/<code>SIGINT</code> it <a href="./deployment/#graceful-shutdown">drains gracefully</a>; a truncated drain exits non-zero.</li><li>On <code>SIGHUP</code> it rebuilds the Lua pool without dropping connections.</li></ul><h2 id="dev" tabindex="-1"><code>dev</code> <a class="header-anchor" href="#dev" aria-label="Permalink to “dev”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>run</code> plus development mode:</p><ul><li><strong>Hot reload.</strong> A file watcher rebuilds the Lua pool when you save the handler script, a file under <code>routes/</code>, or a template. No restart, no dropped connections.</li><li><strong>Error details in responses.</strong> A failing handler answers with the headline, the failing source line, the traceback and the cause chain — as HTML when the client accepts it, plain text otherwise. In production the same failure is exactly <code>Internal Server Error</code>.</li><li><strong>Debug-level logging</strong> by default, which turns on the inner spans (<code>pool_checkout</code>, <code>lua_handler</code>, <code>db_query</code>, <code>fetch</code>) so you can see where the time went.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">Never run dev mode in production</p><p></p><p>It leaks source paths, line numbers and tracebacks to whoever can cause an error. <a href="#build"><code>nitr build</code></a> forces it off for exactly this reason.</p></div><h2 id="check" tabindex="-1"><code>check</code> <a class="header-anchor" href="#check" aria-label="Permalink to “check”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print-config</span></span></code></pre></div><p>Loads the configuration and every script, then exits — <strong>without binding a port</strong>. That makes it the right thing to run in CI, in a pre-deploy step, and after editing <code>nitr.toml</code>.</p><p>It catches: unknown or contradictory configuration keys, missing files and directories, Lua syntax errors, a handler script that forgets to <code>return app</code>, and a builtin configured but not compiled into this binary.</p><p><code>--print-config</code> prints the <strong>effective</strong> configuration after file + environment + flag layering — the answer to &quot;which value actually won?&quot;:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NITR_WORKERS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print-config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;127.0.0.1:3000&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">handler_script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;app.lua&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">workers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><h2 id="test" tabindex="-1"><code>test</code> <a class="header-anchor" href="#test" aria-label="Permalink to “test”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span></span></code></pre></div><p>Runs every <code>*.lua</code> file under <code>[testing] dir</code> (default <code>tests/</code>) against an <strong>in-process server</strong>. Requests dispatch through the real router and the real middleware chain — nothing is mocked.</p><p><code>--filter &lt;SUBSTRING&gt;</code> runs only tests whose name or file name contains the substring. The command exits non-zero if any test fails, so it drops straight into CI. See <a href="./testing">Testing</a>.</p><h2 id="migrate" tabindex="-1"><code>migrate</code> <a class="header-anchor" href="#migrate" aria-label="Permalink to “migrate”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre></div><p>Applies pending <code>.sql</code> files from <code>[database] migrations_dir</code> (default <code>migrations/</code>) in filename order, recording each one as applied.</p><p><code>--status</code> reports what has run and what is pending, applying nothing.</p><p>The server <strong>refuses to start while a migration is pending</strong>, which is what keeps the schema and the code from quietly disagreeing. See <a href="./database#migrations">Database → Migrations</a>.</p><h2 id="init" tabindex="-1"><code>init</code> <a class="header-anchor" href="#init" aria-label="Permalink to “init”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # into the current directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # into my-app/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --minimal</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # the four-file version</span></span></code></pre></div><p>Scaffolds a complete application: <code>nitr.toml</code>, <code>config.lua</code>, <code>app.lua</code>, a route module, a migration, a template, a static page, a test, a <code>.gitignore</code>, and the generated <code>nitr-types.lua</code> completions. See <a href="./project-layout">Project layout</a>.</p><p>It <strong>refuses to overwrite an existing file</strong> — running it in a non-empty directory is safe, it will simply stop.</p><h2 id="build" tabindex="-1"><code>build</code> <a class="header-anchor" href="#build" aria-label="Permalink to “build”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span></code></pre></div><p>Appends the whole application — <code>nitr.toml</code>, every Lua source, templates, static files and migrations — to a copy of the running binary. The result is one executable that no longer depends on the directory it was built in.</p><ul><li><code>dev_mode</code> is forced off: there are no source files to watch.</li><li>The <strong>database stays external</strong>, resolving against the working directory as always. State does not belong inside an immutable artifact.</li><li>A configuration file is required — the bundle records it as the application manifest.</li></ul><p>See <a href="./deployment/single-file">Single-file deploys</a>.</p><h2 id="reload" tabindex="-1"><code>reload</code> <a class="header-anchor" href="#reload" aria-label="Permalink to “reload”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>Sends <code>SIGHUP</code> to the process named by the configured <code>pidfile</code>, which makes it rebuild the Lua runtime pool without dropping connections. The listener, the process and its keep-alive connections all survive.</p><p>Requires <code>pidfile</code> to be set in <code>nitr.toml</code> — without it, <code>reload</code> has no way to find the server and says so. Needs Unix signals, so it is unavailable on Windows.</p><p>Equivalent to <code>kill -HUP &lt;pid&gt;</code>, and to systemd&#39;s <code>ExecReload</code>.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success — including a clean, complete graceful drain.</td></tr><tr><td><code>1</code></td><td>Any failure: a configuration or script error, a failing test, a drain that ran out of time.</td></tr></tbody></table><p><code>[log] format = &quot;json&quot;</code> and exit codes are the machine-readable contract; the human-readable output text is not an API. See <a href="./../stability">Stability</a>.</p>`,48)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
